--
-- Name: collect_account_remark_label(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.collect_account_remark_label() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  admin record;
  trimmed text;
  part text;
BEGIN
  trimmed := btrim(coalesce(NEW.note, ''));
  IF trimmed = '' THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND btrim(coalesce(OLD.note, '')) = trimmed AND OLD.group_id = NEW.group_id THEN
    RETURN NEW;
  END IF;
  FOREACH part IN ARRAY string_to_array(trimmed, chr(30))
  LOOP
    part := btrim(part);
    IF part = '' THEN
      CONTINUE;
    END IF;
    FOR admin IN
      SELECT a.id
      FROM app_user a
      JOIN user_group ug ON ug.user_id = a.id
      WHERE ug.group_id = NEW.group_id
        AND a.role = 'administrator'
        AND a.provisioned_by = 'init-tool'
        AND a.enabled
      ORDER BY a.id
    LOOP
      PERFORM pg_advisory_xact_lock(hashtextextended(
        admin.id::text || ':account:remark:' || part, 0));
      VALUES (admin.id, 'account', 'remark', part)
      ON CONFLICT (administrator_id, scope, kind, name) DO NOTHING;
    END LOOP;
  END LOOP;
  RETURN NEW;
END;
$$;


--
-- Name: collect_business_labels(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.collect_business_labels() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  label record;
BEGIN
  FOR label IN
    SELECT DISTINCT a.id AS administrator_id, tag.name,
      CASE TG_TABLE_NAME
        WHEN 'operation_account' THEN CASE WHEN tag.position = 1 THEN 'account' ELSE 'account-tag' END
        WHEN 'operation_proxy' THEN 'proxy'
        WHEN 'operation_resource' THEN 'resource'
        WHEN 'registration_resource' THEN 'registration'
      END AS scope
    FROM app_user a JOIN user_group ug ON ug.user_id = a.id
    CROSS JOIN unnest(NEW.tags) WITH ORDINALITY AS tag(name, position)
    WHERE ug.group_id = NEW.group_id AND a.role = 'administrator'
      AND a.provisioned_by = 'init-tool' AND a.enabled AND length(trim(tag.name)) > 0
    ORDER BY a.id, scope, tag.name
  LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended(
      label.administrator_id::text || ':' || label.scope || ':group:' || label.name, 0));
    VALUES (label.administrator_id, label.scope, 'group', label.name)
    ON CONFLICT (administrator_id, scope, kind, name) DO NOTHING;
  END LOOP;
  RETURN NEW;
END;
$$;


