--
-- Name: operation_account_device_pair(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.operation_account_device_pair() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (NEW.device_id IS NULL) <> (NEW.device_instance_id IS NULL) THEN
    RAISE EXCEPTION 'device and pit must both be set or both be empty';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: record_device_group(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_device_group() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  VALUES (NEW.id, NEW.group_id) ON CONFLICT DO NOTHING;
  RETURN NEW;
END $$;


--
-- Name: require_current_device_group(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.require_current_device_group() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM device WHERE id = NEW.device_id AND group_id = NEW.group_id AND NOT assignment_pending) THEN
    RAISE EXCEPTION 'device is not assigned to the requested group' USING ERRCODE = '23503';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_device_business_labels(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_device_business_labels() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.box_group_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM business_label l WHERE l.id = NEW.box_group_id AND l.scope = 'device'
      AND l.kind = 'group' AND (
        l.administrator_id = NEW.assignee_user_id OR (
          NEW.assignee_user_id IS NULL AND NEW.assignment_pending AND EXISTS (
            SELECT 1 FROM user_group ug
            WHERE ug.group_id = NEW.group_id AND ug.user_id = l.administrator_id
          )
        )
      )
  ) THEN
    RAISE EXCEPTION 'Invalid device group classification' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: validate_device_remark(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_device_remark() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  owner uuid;
  pending boolean;
  owner_group uuid;
BEGIN
  SELECT assignee_user_id, assignment_pending, group_id
    INTO owner, pending, owner_group
  FROM device WHERE id = NEW.device_id;
  IF NOT FOUND OR NOT EXISTS (
    SELECT 1 FROM business_label l WHERE l.id = NEW.label_id AND l.scope = 'device'
      AND l.kind = 'remark' AND (
        l.administrator_id = owner OR (
          owner IS NULL AND pending AND EXISTS (
            SELECT 1 FROM user_group ug
            WHERE ug.group_id = owner_group AND ug.user_id = l.administrator_id
          )
        )
      )
  ) THEN
    RAISE EXCEPTION 'Invalid device remark classification' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


