--
-- Name: behavior_chain; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.behavior_chain (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    group_id uuid NOT NULL,
    administrator_id uuid NOT NULL,
    created_by uuid NOT NULL,
    name text NOT NULL,
    origin text NOT NULL,
    executor_key text DEFAULT 'box-agent'::text NOT NULL,
    parameters jsonb NOT NULL,
    param_scopes jsonb DEFAULT '[]'::jsonb NOT NULL,
    last_tested_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    guards jsonb DEFAULT '[]'::jsonb NOT NULL,
    delays jsonb DEFAULT '[]'::jsonb NOT NULL,
    anchor_table text DEFAULT ''::text NOT NULL,
    anchor_key text DEFAULT ''::text NOT NULL,
    param_sources jsonb DEFAULT '[]'::jsonb NOT NULL,
    CONSTRAINT behavior_chain_anchor_pair_check CHECK ((((anchor_table = ''::text) AND (anchor_key = ''::text)) OR ((anchor_table = 'operation_account'::text) AND (anchor_key = ANY (ARRAY['id'::text, 'identifier'::text]))))),
    CONSTRAINT behavior_chain_origin_check CHECK ((origin = ANY (ARRAY['rpa'::text, 'ai'::text]))),
    CONSTRAINT behavior_chain_param_sources_array_check CHECK ((jsonb_typeof(param_sources) = 'array'::text))
);


--
-- Name: COLUMN behavior_chain.anchor_table; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.behavior_chain.anchor_table IS '参数约束的数据表，空表示不约束';


--
-- Name: COLUMN behavior_chain.anchor_key; Type: COMMENT; Schema: public; Owner: -
