--
-- Name: business_label; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.business_label (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    administrator_id uuid NOT NULL,
    kind text NOT NULL,
    name text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    scope text DEFAULT 'legacy'::text NOT NULL,
    CONSTRAINT business_label_kind_check CHECK ((kind = ANY (ARRAY['remark'::text, 'group'::text]))),
    CONSTRAINT business_label_name_check CHECK ((length(TRIM(BOTH FROM name)) > 0)),
    CONSTRAINT business_label_scope_check CHECK ((scope = ANY (ARRAY['device'::text, 'account'::text, 'account-tag'::text, 'proxy'::text, 'resource'::text, 'registration'::text, 'legacy'::text])))
);


--
-- Name: box_group; Type: VIEW; Schema: public; Owner: -
