CREATE VIEW public.box_group AS
 SELECT id,
    administrator_id,
    name,
    created_at
   FROM public.business_label
  WHERE ((scope = 'device'::text) AND (kind = 'group'::text))
  WITH LOCAL CHECK OPTION;


