 SELECT id,
    administrator_id,
    name,
    created_at
   FROM public.business_label
  WHERE ((scope = 'device'::text) AND (kind = 'remark'::text))
  WITH LOCAL CHECK OPTION;


--
-- Name: box_share_entry; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.box_share_entry (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    device_id uuid NOT NULL,
    bucket text NOT NULL,
    relative_path text NOT NULL,
    parent_path text NOT NULL,
    name text NOT NULL,
    kind text NOT NULL,
    category text DEFAULT ''::text NOT NULL,
    size_bytes bigint DEFAULT 0 NOT NULL,
    mtime timestamp with time zone,
    sha256 text DEFAULT ''::text NOT NULL,
    last_scan_id uuid NOT NULL,
    seen_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT box_share_entry_bucket_check CHECK ((bucket = ANY (ARRAY['share'::text, 'video'::text, 'mbp'::text, 'backup'::text]))),
    CONSTRAINT box_share_entry_category_check CHECK ((category = ANY (ARRAY[''::text, 'video'::text, 'text'::text, 'image'::text, 'other'::text]))),
    CONSTRAINT box_share_entry_kind_check CHECK ((kind = ANY (ARRAY['dir'::text, 'file'::text]))),
    CONSTRAINT box_share_entry_path_shape CHECK (((name <> ''::text) AND (POSITION(('/'::text) IN (name)) = 0) AND (char_length(relative_path) <= 512) AND (((parent_path = ''::text) AND (relative_path = name)) OR (relative_path = ((parent_path || '/'::text) || name))))),
    CONSTRAINT box_share_entry_sha_check CHECK (((sha256 = ''::text) OR (sha256 ~ '^[0-9a-f]{64}$'::text)))
);


--
-- Name: box_share_scan; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.box_share_scan (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    device_id uuid NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    requested_by uuid,
    started_at timestamp with time zone,
    finished_at timestamp with time zone,
    file_count integer DEFAULT 0 NOT NULL,
    dir_count integer DEFAULT 0 NOT NULL,
    skipped_count integer DEFAULT 0 NOT NULL,
    error text DEFAULT ''::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    buckets text DEFAULT 'share,video,mbp'::text NOT NULL,
    CONSTRAINT box_share_scan_buckets_check CHECK ((buckets = ANY (ARRAY['share,video,mbp'::text, 'backup'::text]))),
    CONSTRAINT box_share_scan_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'running'::text, 'complete'::text, 'failed'::text])))
);


