--
-- Name: operation_account_pool; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.operation_account_pool (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    display_id bigint NOT NULL,
    group_id uuid NOT NULL,
    created_by_user_id uuid NOT NULL,
    key text NOT NULL,
    remark text DEFAULT ''::text NOT NULL,
    back_type text NOT NULL,
    device_id uuid,
    device_seq integer,
    device_label text DEFAULT ''::text NOT NULL,
    times integer DEFAULT 1 NOT NULL,
    member_count integer NOT NULL,
    filter_condition jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone DEFAULT (now() + '30 days'::interval) NOT NULL,
    deleted_at timestamp with time zone,
    CONSTRAINT operation_account_pool_back_type_check CHECK ((back_type = ANY (ARRAY['1'::text, '2'::text, '3'::text, '4'::text, '5'::text]))),
    CONSTRAINT operation_account_pool_device_check CHECK ((((back_type = ANY (ARRAY['1'::text, '2'::text, '4'::text])) AND (device_id IS NOT NULL)) OR ((back_type = ANY (ARRAY['3'::text, '5'::text])) AND (device_id IS NULL)))),
    CONSTRAINT operation_account_pool_key_check CHECK ((((length(TRIM(BOTH FROM key)) >= 1) AND (length(TRIM(BOTH FROM key)) <= 400)) AND (POSITION(('+'::text) IN (key)) = 0))),
    CONSTRAINT operation_account_pool_seq_check CHECK ((((back_type = '1'::text) AND ((device_seq IS NULL) OR ((device_seq >= 1) AND (device_seq <= 12)))) OR ((back_type <> '1'::text) AND (device_seq IS NULL)))),
    CONSTRAINT operation_account_pool_size_check CHECK (((member_count >= 0) AND (member_count <= 3000))),
    CONSTRAINT operation_account_pool_times_check CHECK (((times >= 1) AND (times <= 20)))
);


--
-- Name: COLUMN operation_account_pool.filter_condition; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.operation_account_pool.filter_condition IS '旧池保存来源筛选。新池保存 kind=desk 的账号管理筛选，成员按这些条件实时计算。';


