    id uuid DEFAULT gen_random_uuid() NOT NULL,
    item_id uuid NOT NULL,
    sequence integer NOT NULL,
    skill text NOT NULL,
    sources jsonb NOT NULL,
    scopes jsonb NOT NULL,
    parameters jsonb NOT NULL,
    fill_status text NOT NULL,
    missing_keys text[] DEFAULT '{}'::text[] NOT NULL,
    text_resource_id uuid,
    guards jsonb DEFAULT '[]'::jsonb NOT NULL,
    after_ms integer DEFAULT 0 NOT NULL,
    CONSTRAINT operation_dispatch_step_fill_check CHECK ((fill_status = ANY (ARRAY['complete'::text, 'incomplete'::text])))
);


--
-- Name: operation_log; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.operation_log (
    id bigint NOT NULL,
    group_id uuid NOT NULL,
    actor_id uuid,
    device_id uuid,
    level text NOT NULL,
    text text NOT NULL,
    dedup_key text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT operation_log_level_check CHECK ((level = ANY (ARRAY['info'::text, 'ok'::text, 'error'::text])))
);


--
-- Name: operation_log_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

CREATE SEQUENCE public.operation_log_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: operation_log_id_seq; Type: SEQUENCE OWNED BY; Schema: public; Owner: -
--

ALTER SEQUENCE public.operation_log_id_seq OWNED BY public.operation_log.id;


--
-- Name: operation_proxy; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.operation_proxy (
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    encrypted_credentials text NOT NULL,
    endpoint text NOT NULL,
    group_id uuid NOT NULL,
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    note text DEFAULT ''::text NOT NULL,
    status public.operation_proxy_status DEFAULT 'ready'::public.operation_proxy_status NOT NULL,
    tags text[] DEFAULT '{}'::text[] NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    display_id bigint NOT NULL,
    configuration jsonb,
    revision bigint DEFAULT 1 NOT NULL,
    check_result jsonb,
    probe_token uuid,
    probe_started_at timestamp with time zone,
    CONSTRAINT operation_proxy_configuration_object CHECK (((configuration IS NULL) OR (jsonb_typeof(configuration) = 'object'::text))),
    CONSTRAINT operation_proxy_result_object CHECK (((check_result IS NULL) OR (jsonb_typeof(check_result) = 'object'::text))),
    CONSTRAINT operation_proxy_revision_positive CHECK ((revision > 0))
);


--
-- Name: operation_proxy_accelerator; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.operation_proxy_accelerator (
    group_id uuid NOT NULL,
    proxy_id uuid NOT NULL,
    accelerator_id uuid NOT NULL,
    "position" integer NOT NULL,
    CONSTRAINT operation_proxy_accelerator_check CHECK ((proxy_id <> accelerator_id)),
    CONSTRAINT operation_proxy_accelerator_position_check CHECK ((("position" >= 0) AND ("position" <= 10)))
);


--
-- Name: operation_proxy_display_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

ALTER TABLE public.operation_proxy ALTER COLUMN display_id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.operation_proxy_display_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


